import json
from types import SimpleNamespace
out={}
def optional(probs,top):
    next_token=7
    if probs: pass
    else: next_prob=None
    if top: pass
    else: next_k_tokens,next_k_probs=None,None
    return next_token,next_k_tokens,next_k_probs,next_prob
out['optional']={}
for p,k in [(False,0),(True,0),(False,3)]:
    try: out['optional'][str((p,k))]=optional(p,k)
    except UnboundLocalError as e: out['optional'][str((p,k))]=str(e)
P=256
lengths=[1,1]; budget=100
context=[(n-1)//P for n in lengths]
private=[(n+budget+P-1)//P-c for n,c in zip(lengths,context)]
out['capacity']={'private_pages':private,'enqueue_total':private[-1],'start_required':sum(private),'cache_pages':1}
s=SimpleNamespace(held_tokens=[7],held_text='bad',new_tokens=1,sequence=[11,7],kv_position=1)
checkpoint={'offset':1,'held_tokens':[],'held_text':''}
s.new_tokens-=checkpoint['offset']; s.sequence=s.sequence[:-1]; s.kv_position-=1
suppressed=s.held_tokens[len(checkpoint['held_tokens']):]
s.held_text=checkpoint['held_text']; s.held_token=checkpoint['held_tokens']
out['rewind']={'emitted_token_ids':s.held_tokens[:],'suppressed_tokens':suppressed,'sequence_after':s.sequence,'new_tokens':s.new_tokens}
out['draft_rows']={'jobs':1,'sequences':2,'allocated_rows':1,'rows_written':2}
out['prefill']=[{'chunk':chunk,'position':0,'end':min((chunk//P)*P,299)} for chunk in [255,256,2048]]
out['terminal_banned']={'new_tokens':1,'max_new_tokens':1,'draft_tokens':0,'max_branch_before_banned_match':1>=1-0,'emitted_held_text':'bad'}
print(json.dumps(out,sort_keys=True))

